17	    /// Ensures that ARIA properties `aria-*` are all valid.
18	    ///
19	    /// ## Examples
20	    ///
21	    /// ### Invalid
22	    ///
23	    /// ```html,expect_diagnostic
24	    /// <input type="text" aria-labell="" />
25	    /// ```
26	    ///
27	    /// ```html,expect_diagnostic
28	    /// <div aria-lorem="foobar"></div>
29	    /// ```
30	    ///
31	    /// ### Valid
32	    ///
33	    /// ```html
34	    /// <input type="text" aria-label="Enter your name" />
35	    /// <div aria-hidden="true"></div>
36	    /// ```
37	    ///
38	    /// ## Accessibility guidelines
39	    /// - [WCAG 4.1.2](https://www.w3.org/WAI/WCAG21/Understanding/name-role-value)
40	    pub UseValidAriaProps {
41	        version: "next",
42	        name: "useValidAriaProps",
43	        language: "html",
44	        sources: &[RuleSource::EslintJsxA11y("aria-props").same()],
45	        recommended: true,
46	        severity: Severity::Error,
47	        fix_kind: FixKind::Unsafe,
48	    }
49	}
