51	impl Rule for UseValidAriaProps {
52	    type Query = Ast<AnyHtmlAttribute>;
53	    type State = ();
54	    type Signals = Option<Self::State>;
55	    type Options = UseValidAriaPropsOptions;
56	
57	    fn run(ctx: &RuleContext<Self>) -> Option<Self::State> {
58	        let attr = ctx.query();
59	        let name = extract_attribute_name(attr)?;
60	        let name_lower = name.to_ascii_lowercase_cow();
61	        if name_lower.starts_with("aria-") && AriaAttribute::from_str(&name_lower).is_err() {
62	            Some(())
63	        } else {
64	            None
65	        }
66	    }
67	
68	    fn diagnostic(ctx: &RuleContext<Self>, _state: &Self::State) -> Option<RuleDiagnostic> {
69	        let attr = ctx.query();
70	        let name = extract_attribute_name(attr)?;
71	        Some(
72	            RuleDiagnostic::new(
73	                rule_category!(),
74	                attr.range(),
75	                markup! {
76	                    "The element contains an invalid ARIA attribute."
77	                },
78	            )
79	            .detail(
80	                attr.range(),
81	                markup! {
82	                    <Emphasis>{name.text()}</Emphasis>" is not a valid ARIA attribute."
83	                },
84	            ),
85	        )
86	    }
87	
88	    fn action(ctx: &RuleContext<Self>, _state: &Self::State) -> Option<HtmlRuleAction> {
89	        let attr = ctx.query();
90	        let mut mutation = ctx.root().begin();
91	        mutation.remove_node(attr.clone());
92	        Some(HtmlRuleAction::new(
93	            ctx.metadata().action_category(ctx.category(), ctx.group()),
94	            ctx.metadata().applicability(),
95	            markup! { "Remove the invalid "<Emphasis>"aria-*"</Emphasis>" attribute.
96	                Check the list of all "<Hyperlink href="https://developer.mozilla.org/en-US/docs/web/Accessibility/ARIA/Attributes#aria_attribute_types">"valid"</Hyperlink>" aria-* attributes." }
97	                .to_owned(),
98	            mutation,
99	        ))
100	    }
101	}
