103	fn extract_attribute_name(attr: &AnyHtmlAttribute) -> Option<TokenText> {
104	    match attr {
105	        AnyHtmlAttribute::HtmlAttribute(a) => {
106	            Some(a.name().ok()?.value_token().ok()?.token_text_trimmed())
107	        }
108	        AnyHtmlAttribute::AnyVueDirective(vue) => match vue {
109	            AnyVueDirective::VueVBindShorthandDirective(d) => Some(
110	                d.arg()
111	                    .ok()?
112	                    .arg()
113	                    .ok()?
114	                    .as_vue_static_argument()?
115	                    .name_token()
116	                    .ok()?
117	                    .token_text_trimmed(),
118	            ),
119	            AnyVueDirective::VueDirective(d) => {
120	                if d.name_token().ok()?.text_trimmed() != "v-bind" {
121	                    return None;
122	                }
123	                Some(
124	                    d.arg()?
125	                        .arg()
126	                        .ok()?
127	                        .as_vue_static_argument()?
128	                        .name_token()
129	                        .ok()?
130	                        .token_text_trimmed(),
131	                )
132	            }
133	            _ => None,
134	        },
135	        _ => None,
136	    }
137	}
