13	    /// Enforce that ARIA state and property values are valid.
14	    ///
15	    /// ## Examples
16	    ///
17	    /// ### Invalid
18	    ///
19	    /// ```jsx, expect_diagnostic
20	    /// <span role="checkbox" aria-checked="test">some text</span>
21	    /// ```
22	    ///
23	    /// ```jsx, expect_diagnostic
24	    /// <span aria-labelledby="">some text</span>
25	    /// ```
26	    ///
27	    /// ```jsx, expect_diagnostic
28	    /// <span aria-valuemax="hey">some text</span>
29	    /// ```
30	    ///
31	    /// ```jsx, expect_diagnostic
32	    /// <span aria-orientation="hey">some text</span>
33	    /// ```
34	    ///
35	    /// ### Valid
36	    ///
37	    /// ```jsx
38	    /// <>
39	    ///     <span role="checkbox" aria-checked={checked} >some text</span>
40	    ///     <span aria-labelledby="fooId barId" >some text</span>
41	    /// </>
42	    /// ```
43	    ///
44	    /// ## Accessibility guidelines
45	    ///
46	    /// - [WCAG 4.1.2](https://www.w3.org/WAI/WCAG21/Understanding/name-role-value)
47	    ///
48	    /// ### Resources
49	    ///
50	    /// - [ARIA Spec, States and Properties](https://www.w3.org/TR/wai-aria/#states_and_properties)
51	    /// - [Chrome Audit Rules, AX_ARIA_04](https://github.com/GoogleChrome/accessibility-developer-tools/wiki/Audit-Rules#ax_aria_04)
52	    pub UseValidAriaValues {
53	        version: "1.0.0",
54	        name: "useValidAriaValues",
55	        language: "jsx",
56	        sources: &[RuleSource::EslintJsxA11y("aria-proptypes").same()],
57	        recommended: true,
58	        severity: Severity::Error,
59	    }
60	}
