68	impl Rule for UseValidAriaValues {
69	    type Query = Ast<JsxAttribute>;
70	    type State = UseValidAriaValuesState;
71	    type Signals = Option<Self::State>;
72	    type Options = UseValidAriaValuesOptions;
73	
74	    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
75	        let node = ctx.query();
76	        let attribute_name = node.name().ok()?.as_jsx_name()?.value_token().ok()?;
77	
78	        if let Ok(aria_property) = AriaAttribute::from_str(attribute_name.text_trimmed()) {
79	            let attribute_static_value = node.as_static_value()?;
80	            let attribute_text = attribute_static_value.text();
81	            if !aria_property.value_type().contains(attribute_text) {
82	                return Some(UseValidAriaValuesState {
83	                    attribute_name,
84	                    attribute_value_range: node.range(),
85	                    property_type: aria_property.value_type(),
86	                });
87	            }
88	        }
89	
90	        None
91	    }
92	
93	    fn diagnostic(_ctx: &RuleContext<Self>, state: &Self::State) -> Option<RuleDiagnostic> {
94	        let attribute_name = state.attribute_name.text_trimmed();
95	        let diagnostic = RuleDiagnostic::new(
96	            rule_category!(),
97	            state.attribute_value_range,
98	            markup! {
99	                "The value of the ARIA attribute "<Emphasis>{attribute_name}</Emphasis>" is not correct."
100	            },
101	        );
102	        let diagnostic = match state.property_type {
103	            AriaValueType::Boolean => {
104	                diagnostic.footer_list(
105	                    markup!{
106	                        "The only supported values for the "<Emphasis>{attribute_name}</Emphasis>" property is one of the following:"
107	                    },
108	                    ["false", "true"]
109	                )
110	            }
111	            AriaValueType::OptionalBoolean => {
112	                diagnostic.footer_list(
113	                    markup!{
114	                        "The only supported values for the "<Emphasis>{attribute_name}</Emphasis>" property is one of the following:"
115	                    },
116	                    ["undefined", "false", "true"]
117	                )
118	            }
119	            AriaValueType::Integer => {
120	                diagnostic.note(
121	                    markup!{
122	                        "The only value supported is a number without fractional components."
123	                    }
124	                )
125	            }
126	            AriaValueType::IdReference => {
127	                diagnostic.note(
128	                    markup!{
129	                        "The only supported value is an HTML identifier."
130	                    }
131	                )
132	            }
133	            AriaValueType::IdReferenceList => {
134	                diagnostic.note(
135	                    markup!{
136	                        "The only supported value is a space-separated list of HTML identifiers."
137	                    }
138	                )
139	            }
140	            AriaValueType::String => {
141	                diagnostic.note(
142	                    markup!{
143	                        "The only supported value is text."
144	                    }
145	                )
146	            }
147	            AriaValueType::Number => {
148	                diagnostic.note(
149	                    markup!{
150	                        "The only supported value is number."
151	                    }
152	                )
153	            }
154	            AriaValueType::Token(tokens) => {
155	                diagnostic.footer_list(
156	                    markup!{
157	                    "The only supported value for the "<Emphasis>{attribute_name}</Emphasis>" property is one of the following:"
158	                },
159	                    tokens
160	                )
161	            }
162	            AriaValueType::TokenList(tokens) => {
163	                diagnostic.footer_list(
164	                    markup!{
165	                    "The values supported for "<Emphasis>{attribute_name}</Emphasis>" property are one or more of the following:"
166	                },
167	                    tokens
168	                )
169	            }
170	            AriaValueType::Tristate => {
171	                diagnostic.footer_list(
172	                    markup!{
173	                        "The only supported value for the "<Emphasis>{attribute_name}</Emphasis>" property one of the following:"
174	                    },
175	                    ["false", "true", "mixed"]
176	                )
177	            }
178	        };
179	        Some(diagnostic)
180	    }
181	}
