79	pub enum AriaValueType {
80	    /// `false`/`true`
81	    Boolean,
82	    IdReference,
83	    IdReferenceList,
84	    Integer,
85	    Number,
86	    /// `undefined`/`false`/`true`
87	    OptionalBoolean,
88	    /// Non-empty string
89	    String,
90	    /// A token among the given slice of tokens
91	    Token(&'static [&'static str]),
92	    /// A list of tokens among the given slice of tokens
93	    TokenList(&'static [&'static str]),
94	    /// `false`/`true`/`mixed`
95	    Tristate,
96	}
97	impl AriaValueType {
98	    /// It checks if `value` is valid for the `self` type.
99	    ///
100	    /// [Source](https://www.w3.org/TR/wai-aria-1.2/#propcharacteristic_value)
101	    ///
102	    /// ## Examples
103	    ///
104	    /// ```
105	    /// use biome_aria_metadata::AriaAttribute;
106	    ///
107	    /// assert!(AriaAttribute::AriaCurrent.value_type().contains("true"));
108	    /// assert!(AriaAttribute::AriaCurrent.value_type().contains("step"));
109	    ///
110	    /// assert!(!AriaAttribute::AriaCurrent.value_type().contains("something_not_allowed"));
111	    /// ```
112	    pub fn contains(&self, value: &str) -> bool {
113	        if value.is_empty() {
114	            return false;
115	        }
116	        match self {
117	            Self::String => true,
118	            Self::IdReference => is_valid_html_id(value),
119	            Self::IdReferenceList => value.split_ascii_whitespace().all(is_valid_html_id),
120	            Self::Integer => value.parse::<u32>().is_ok(),
121	            Self::Number => value.parse::<f32>().is_ok(),
122	            Self::Boolean => matches!(value, "false" | "true"),
123	            Self::OptionalBoolean => matches!(value, "undefined" | "false" | "true"),
124	            Self::Token(tokens) => tokens.contains(&value),
125	            Self::TokenList(tokens) => value.split_ascii_whitespace().all(|input_token| {
126	                tokens
127	                    .iter()
128	                    .any(|allowed_token| allowed_token.trim() == input_token)
129	            }),
130	            Self::Tristate => matches!(value, "false" | "true" | "mixed"),
131	        }
132	    }
133	}
