135	/// Is `id` a valid HTML identifier?
136	///
137	/// Browsers allows arbitrary sequence of characters for identifiers.
138	/// However, it is commonly accepted that an identifier should not contain
139	/// characters recognized as whitespaces by HTML.
140	/// Whitespaces are usedd to separate two identifier in a list of identifiers.
141	///
142	/// See https://developer.mozilla.org/en-US/docs/Web/HTML/Global_attributes/id#syntax
143	fn is_valid_html_id(id: &str) -> bool {
144	    !id.is_empty() && !id.bytes().any(|b| b.is_ascii_whitespace())
145	}
