147	impl AriaRole {
148	    /// Returns the first valid role from `roles`, a space-separated list of roles.
149	    ///
150	    /// If a role attribute has multiple values, the first valid role (specified role) will be used.
151	    /// See <https://www.w3.org/TR/2014/REC-wai-aria-implementation-20140320/#mapping_role>
152	    ///
153	    /// ```
154	    /// use biome_aria_metadata::AriaRole;
155	    /// assert_eq!(AriaRole::from_roles("INVALID main FALLBACK"), Some(AriaRole::Main));
156	    /// ```
157	    pub fn from_roles(roles: &str) -> Option<Self> {
158	        roles
159	            .split_ascii_whitespace()
160	            .find_map(|value| value.parse().ok())
161	    }
162	
163	    /// Returns `true` if the given role inherits of `AriaAbstractRole::Widget` and is not `Self::Progressbar`.
164	    ///
165	    /// This corresponds to a role that defines a user interface widget (slider, tree control, ...)
166	    pub fn is_interactive(self) -> bool {
167	        // `progressbar` inherits of `widget`, but its value is always `readonly`.
168	        // So we treat it as a non-interactive role.
169	        self != Self::Progressbar
170	            && self
171	                .inherited_abstract_roles()
172	                .contains(&AriaAbstractRole::Widget)
173	    }
174	
175	    /// Returns `true` if the given role is not interactive and is not `Self::Toolbar`.
176	    pub fn is_non_interactive(self) -> bool {
177	        // FIXME: could we make `Self""is_non_interactive` the negation of `Self""is_interactive`?
178	        //
179	        // This current asymetry is ported from  ESLint JSX A11y:
180	        // https://github.com/jsx-eslint/eslint-plugin-jsx-a11y/blob/main/src/util/isNonInteractiveElement.js#L30
181	        // We should assess if this asymetry is intended.
182	        //
183	        // `toolbar` doesn't inherit of `widget`, but it does support  `aria-activedescendant`.
184	        // So, we treat it as a interactive role.
185	        self != Self::Toolbar && !self.is_interactive()
186	    }
187	
188	    /// Returns `true` if the given role inherits of `AriaAbstractRole::Structure`.
189	    ///
190	    /// This corresponds to a role that defines the page structure (section, navigation, ...).
191	    pub fn is_presentational(self) -> bool {
192	        self.inherited_abstract_roles()
193	            .contains(&AriaAbstractRole::Structure)
194	    }
195	
196	    /// Returns `true` if the given role inherits of `AriaAbstractRole::Composite`.
197	    pub fn is_composite(self) -> bool {
198	        self.inherited_abstract_roles()
199	            .contains(&AriaAbstractRole::Composite)
200	    }
201	}
