use biome_rowan::{AstNode, TokenText};
use biome_rule_options::use_valid_aria_values::UseValidAriaValuesOptions;
use biome_string_case::StrLikeExtension;

declare_lint_rule! {
    /// Enforce that ARIA state and property values are valid.
    ///
    /// This rule validates statically written ARIA attribute values against the
    /// WAI-ARIA specification. It applies to HTML as well as to the template
    /// portions of Astro, Svelte, and Vue single-file components.
    ///
    /// In HTML files, ARIA attribute names are matched case-insensitively.
    /// Valueless ARIA attributes (e.g. `<div aria-hidden>`) are treated as if
    /// their value were `"true"`. Dynamically bound values (such as Vue's
    /// `:aria-*` or `v-bind:aria-*` bindings) are not checked.
    ///
    /// ## Examples
    ///
    /// ### Invalid
    ///
    /// ```html,expect_diagnostic
    /// <span aria-checked="test">some text</span>
    /// ```
    ///
    /// ```html,expect_diagnostic
    /// <span aria-labelledby="">some text</span>
    /// ```
    ///
    /// ```html,expect_diagnostic
    /// <span aria-valuemax="hey">some text</span>
    /// ```
    ///
    /// ```html,expect_diagnostic
    /// <span aria-orientation="hey">some text</span>
    /// ```
    ///
    /// ### Valid
    ///
    /// ```html
    /// <span aria-checked="true">some text</span>
    /// <span aria-labelledby="fooId barId">some text</span>
    /// ```
    ///
    /// ## Accessibility guidelines
    ///
    /// - [WCAG 4.1.2](https://www.w3.org/WAI/WCAG21/Understanding/name-role-value)
    ///
    /// ### Resources
    ///
    /// - [ARIA Spec, States and Properties](https://www.w3.org/TR/wai-aria/#states_and_properties)
    /// - [Chrome Audit Rules, AX_ARIA_04](https://github.com/GoogleChrome/accessibility-developer-tools/wiki/Audit-Rules#ax_aria_04)
    pub UseValidAriaValues {
        version: "next",
        name: "useValidAriaValues",
        language: "html",
        sources: &[RuleSource::EslintJsxA11y("aria-proptypes").inspired()],
        recommended: true,
        severity: Severity::Error,
    }
}

pub struct UseValidAriaValuesState {
    attribute_name: TokenText,
    property_type: AriaValueType,
}

impl Rule for UseValidAriaValues {
    type Query = Ast<HtmlAttribute>;
    type State = UseValidAriaValuesState;
    type Signals = Option<Self::State>;
    type Options = UseValidAriaValuesOptions;

    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
        let attribute = ctx.query();
        let attribute_name = attribute.name().ok()?.value_token().ok()?.token_text_trimmed();

        // HTML attribute names are case-insensitive, while component templates
        // (Astro, Svelte, Vue) preserve the case of the attribute name.
        let source_type = ctx.source_type::<HtmlFileSource>();
        let lowercased_name;
        let name_to_match: &str = if source_type.is_html() {
            lowercased_name = attribute_name.to_ascii_lowercase_cow();
            &lowercased_name
        } else {
            attribute_name.text()
        };

        let aria_attribute = AriaAttribute::from_str(name_to_match).ok()?;

        // A valueless attribute (`<div aria-hidden>`) is treated as `"true"`.
        // A dynamically bound value cannot be statically resolved, so it is
        // skipped entirely.
        let attribute_value = match attribute.initializer() {
            Some(initializer) => initializer.value().ok()?.string_value()?.to_string(),
            None => String::from("true"),
        };

        if aria_attribute.value_type().contains(&attribute_value) {
            return None;
        }

        Some(UseValidAriaValuesState {
            attribute_name,
            property_type: aria_attribute.value_type(),
        })
    }

    fn diagnostic(ctx: &RuleContext<Self>, state: &Self::State) -> Option<RuleDiagnostic> {
        let attribute = ctx.query();
        let attribute_name = state.attribute_name.text();

        let diagnostic = RuleDiagnostic::new(
            rule_category!(),
            attribute.range(),
            markup! {
                "The value of the ARIA attribute "<Emphasis>{attribute_name}</Emphasis>" is not correct."
            },
        );

        let diagnostic = match state.property_type {
            AriaValueType::Boolean => diagnostic.footer_list(
                markup! {
                    "The only supported values for the "<Emphasis>{attribute_name}</Emphasis>" property are:"
                },
                ["false", "true"],
            ),
            AriaValueType::OptionalBoolean => diagnostic.footer_list(
                markup! {
                    "The only supported values for the "<Emphasis>{attribute_name}</Emphasis>" property are:"
                },
                ["undefined", "false", "true"],
            ),
