</template>"#;
    let msgs = run(src, HtmlFileSource::vue());
    eprintln!("VUE diagnostics: {}", msgs.len());
    for m in &msgs {
        eprintln!("--- {m}");
    }
    assert_eq!(msgs.len(), 1, "only the static aria-hidden should flag");
}
